unsigned int data = 0xAB;    // 1010 1011
unsigned int mask = 0xF0;    // 1111 0000
unsigned int flag = 0x04;    // 0000 0100

// Masking: Zeroes out bits where mask bit is 0
unsigned int upper_nibble = data & mask;  // Result: 0xA0

// Checking if a specific flag is set
if (data & flag) {
    // Flag is set (0xAB & 0x04 = 0x04)
}

// Clearing a bit (using bitwise NOT ~)
const unsigned int CLEAR_BIT_2 = ~(1 << 2);
data = data & CLEAR_BIT_2; // Bit 2 is now 0

// Isolating the Nth bit value (0 or 1)
unsigned int bit_3_value = (data >> 3) & 1;
